package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import javax.sql.DataSource;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class CourseMySubmissionsIntegrationTest {
 record Bound(CourseStore store,UUID id) {}
 static Bound bind(DataSource source,UUID group,UUID space,UUID study,UUID owner,String trace){var store=new CourseStore(source,Clock.systemUTC());var c=store.create(group,space,owner,UUID.randomUUID().toString().replace("-",""),"Own submission Course","Shared",trace).course();store.curriculum(group,space,c.courseId(),owner,1,List.of(study),trace);return new Bound(store,c.courseId());}
 SubmissionGradeStoreIntegrationTest f;CourseMySubmissionsStore store;GradeRetractionStore markers;Bound course;
 @BeforeEach void setup(){f=new SubmissionGradeStoreIntegrationTest();f.setup();course=bind(f.f.f.source,f.f.group,f.f.space,f.f.study,f.f.f.owner,f.f.f.trace);store=new CourseMySubmissionsStore(f.f.f.source,course.store());markers=new GradeRetractionStore(f.f.f.source,f.f.parent.store,f.f.store,Clock.systemUTC());}
 CourseMySubmissionsStore.Page list(String filter,UUID after,int limit){return store.list(f.f.group,f.f.space,course.id(),f.f.author,after,limit,filter);}
 CourseMySubmissionsStore.Row row(){return list("ALL",null,100).items().stream().filter(v->v.submissionId().equals(f.answer.submissionId())).findFirst().orElseThrow();}
 GradeRetractionStore.Retraction mark(long target,long expected,String state){return markers.change(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.f.owner,target,expected,new GradeRetractionInput(state,"PRIVATE annotation reason"),f.f.f.trace);}
 UUID task(UUID study){var id=f.f.parent.store.create(f.f.group,f.f.space,study,f.f.f.owner,f.f.f.key(),"Task <script>","Shared",f.f.f.trace).assignment().assignmentId();f.f.parent.store.state(f.f.group,f.f.space,study,id,f.f.f.owner,1,"OPEN",f.f.f.trace);return id;}
 @Test void zeroScoreCountsAsCurrentAndResubmissionMakesOnlyOldAnswerGradeOutdated(){var grade=f.store.change(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.f.owner,0,new SubmissionGradeInput(0,"PRIVATE zero-grade reason",1,2),f.f.f.trace);assertEquals(0,grade.score());assertEquals("CURRENT",row().gradingStatus());assertTrue(list("NEEDS_GRADING",null,20).items().isEmpty());assertEquals(1,list("CURRENT",null,20).items().size());f.f.submit(f.f.f.key(),1,2,"NEW PRIVATE ANSWER");assertEquals("OUTDATED",row().gradingStatus());assertEquals(2,row().version());assertEquals(1L,row().gradedSubmissionVersion());assertEquals(1,list("OUTDATED",null,20).items().size());assertTrue(list("CURRENT",null,20).items().isEmpty());f.change(1,2,"PRIVATE new-answer grade");assertEquals("CURRENT",row().gradingStatus());assertEquals(2L,row().gradeVersion());assertEquals(2L,row().gradedSubmissionVersion());}
 @Test void onlyLatestGradeVersionMarkerAffectsCurrentAnswerStatus(){f.change(0,1,"First grade");mark(1,0,"RETRACTED");assertEquals("RETRACTED",row().gradingStatus());assertEquals(1,list("RETRACTED",null,20).items().size());mark(1,1,"RESTORED");assertEquals("CURRENT",row().gradingStatus());assertEquals("RESTORED",row().gradeRetractionState());f.change(1,1,"New independently reviewed grade");mark(1,2,"RETRACTED");assertEquals("CURRENT",row().gradingStatus());assertEquals("NONE",row().gradeRetractionState());assertNull(row().retractionVersion());assertTrue(list("RETRACTED",null,20).items().isEmpty());mark(2,0,"RETRACTED");assertEquals("RETRACTED",row().gradingStatus());assertEquals(1L,row().retractionVersion());assertEquals(1,list("NEEDS_GRADING",null,20).items().size());mark(2,1,"RESTORED");assertEquals("CURRENT",row().gradingStatus());assertEquals(2L,row().retractionVersion());}
 @Test void withdrawnOldAnswerStaysOutdatedAndHistoricalMarkerCannotInvalidateNewGrade(){f.change(0,1,"First");f.f.submit(f.f.f.key(),1,2,"Second answer");mark(1,0,"RETRACTED");assertEquals("OUTDATED",row().gradingStatus());assertEquals("RETRACTED",row().gradeRetractionState());assertTrue(list("RETRACTED",null,20).items().isEmpty());assertEquals(1,list("NEEDS_GRADING",null,20).items().size());f.change(1,2,"Second grade");assertEquals("CURRENT",row().gradingStatus());assertEquals("NONE",row().gradeRetractionState());}
 @Test void unknownOrMissingMarkerStateIsNeverReportedAsCurrent(){f.change(0,1,"Grade");var marker=mark(1,0,"RETRACTED");String saved=f.f.f.jdbc.queryForObject("SELECT snapshot::text FROM grade_retraction WHERE retraction_id=?",String.class,marker.retractionId());try{for(String expression:List.of("jsonb_set(snapshot,'{state}','\"INVALID\"')","snapshot-'state'")){f.f.f.jdbc.update("UPDATE grade_retraction SET snapshot="+expression+" WHERE retraction_id=?",marker.retractionId());assertEquals("UNAVAILABLE",row().gradingStatus());assertEquals("UNKNOWN",row().gradeRetractionState());assertTrue(list("CURRENT",null,20).items().isEmpty());assertEquals(1,list("UNAVAILABLE",null,20).items().size());assertEquals(1,list("NEEDS_GRADING",null,20).items().size());}}finally{f.f.f.jdbc.update("UPDATE grade_retraction SET snapshot=?::jsonb WHERE retraction_id=?",saved,marker.retractionId());}}
 @Test void closedArchivedReadsPreserveOriginalGradeFeedbackAndAudit(){var grade=f.change(0,1,"Grade");var marker=mark(1,0,"RETRACTED");f.f.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,2,"CLOSED",f.f.f.trace);f.f.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,3,"RETIRED",f.f.f.trace);f.f.parent.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.f.owner,1,"RETIRED",f.f.f.trace);int count=f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);for(var filter:CourseMySubmissionsStore.FILTERS)list(filter,null,20);assertEquals("RETRACTED",row().gradingStatus());assertEquals(grade,f.get(f.f.author,false).grade());assertEquals(marker,markers.get(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.author,false,1).retraction());assertEquals(count,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));}
 @Test void concurrentNewAnswerAndGradeAreReadAsOneStatementSnapshot()throws Exception{f.change(0,1,"First");try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var barrier=new CyclicBarrier(2);var reads=pool.submit(()->{barrier.await();for(int n=0;n<30;n++){var v=row();assertTrue(v.gradedSubmissionVersion()<=v.version());if(v.gradingStatus().equals("CURRENT"))assertEquals(v.version(),v.gradedSubmissionVersion());else assertEquals("OUTDATED",v.gradingStatus());}return true;});var writes=pool.submit(()->{barrier.await();f.f.submit(f.f.f.key(),1,2,"New answer");return f.change(1,2,"New grade");});assertTrue(reads.get(20,TimeUnit.SECONDS));assertEquals(2,writes.get(20,TimeUnit.SECONDS).version());assertEquals("CURRENT",row().gradingStatus());}}

 @Test void rubricComputedZeroAndDirectModeUseTheSameQueueAndExactMarker(){var g=new RubricGradingStoreIntegrationTest();g.setup();var bound=bind(g.f.f.f.source,g.f.f.group,g.f.f.space,g.f.f.study,g.f.f.f.owner,g.f.f.f.trace);var q=new CourseMySubmissionsStore(g.f.f.f.source,bound.store());var zero=g.change(0,g.input(0,0,"PRIVATE rubric zero"));assertEquals(0,zero.grade().score());var row=q.list(g.f.f.group,g.f.f.space,bound.id(),g.author,null,20,"CURRENT").items().getFirst();assertEquals("CURRENT",row.gradingStatus());assertEquals(1L,row.gradeVersion());var markers=new GradeRetractionStore(g.f.f.f.source,g.f.f.store,g.submissions,Clock.systemUTC());markers.change(g.f.f.group,g.f.f.space,g.f.f.study,g.f.assignment,g.answer.submissionId(),g.f.f.f.owner,1,0,new GradeRetractionInput("RETRACTED","PRIVATE reason"),g.f.f.f.trace);assertEquals(1,q.list(g.f.f.group,g.f.f.space,bound.id(),g.author,null,20,"NEEDS_GRADING").items().size());g.change(1,g.direct(0,"PRIVATE direct zero",1,2));var next=q.list(g.f.f.group,g.f.f.space,bound.id(),g.author,null,20,"CURRENT").items().getFirst();assertEquals(2L,next.gradeVersion());assertEquals("NONE",next.gradeRetractionState());}


 @Test void ownScopeCurrentCurriculumAndLabelsPreserveSourceAndNeverEnroll(){
  UUID peer=f.f.f.ids.next();var other=f.f.store.submit(f.f.group,f.f.space,f.f.study,f.f.assignment,peer,0,2,f.f.f.key(),"PEER SECRET",f.f.f.trace).submission();var self=f.f.store.submit(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,0,2,f.f.f.key(),"OWNER SECRET",f.f.f.trace).submission();assertEquals(1,list("ALL",null,20).items().size());assertEquals(other.submissionId(),store.list(f.f.group,f.f.space,course.id(),peer,null,20,"ALL").items().getFirst().submissionId());assertEquals(self.submissionId(),store.list(f.f.group,f.f.space,course.id(),f.f.f.owner,null,20,"ALL").items().getFirst().submissionId());var json=tools.jackson.databind.json.JsonMapper.builder().build().valueToTree(row());assertEquals(15,json.size());for(String key:List.of("authorId","score","reason","content","graderId","snapshot","audience"))assertFalse(json.has(key));assertEquals("MISSING",row().gradingStatus());
  var b=f.f.parent.parent.create(f.f.f.key()).study();var out=f.f.parent.parent.create(f.f.f.key()).study();UUID bTask=task(b.studyId()),outTask=task(out.studyId());f.f.store.submit(f.f.group,f.f.space,b.studyId(),bTask,f.f.author,0,2,f.f.f.key(),"MY B ANSWER",f.f.f.trace);f.f.store.submit(f.f.group,f.f.space,out.studyId(),outTask,f.f.author,0,2,f.f.f.key(),"EXCLUDED",f.f.f.trace);task(b.studyId());var c=course.store().curriculum(f.f.group,f.f.space,course.id(),f.f.f.owner,2,List.of(f.f.study,b.studyId()),f.f.f.trace);assertEquals(2,list("ALL",null,20).items().size());assertTrue(list("ALL",null,20).items().stream().noneMatch(v->v.studyId().equals(out.studyId())));f.f.parent.parent.store.metadata(f.f.group,f.f.space,b.studyId(),f.f.f.owner,1,"Current B title","New",f.f.f.trace);assertEquals("Current B title",list("ALL",null,20).items().stream().filter(v->v.studyId().equals(b.studyId())).findFirst().orElseThrow().studyTitle());assertEquals(b.title(),course.store().get(f.f.group,f.f.space,course.id()).studies().get(1).title());
  c=course.store().curriculum(f.f.group,f.f.space,course.id(),f.f.f.owner,c.version(),List.of(b.studyId()),f.f.f.trace);assertEquals(bTask,list("ALL",null,20).items().getFirst().assignmentId());assertEquals(1,list("ALL",null,20).items().size());c=course.store().state(f.f.group,f.f.space,course.id(),f.f.f.owner,c.version(),"RETIRED",f.f.f.trace);int events=f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);for(String filter:CourseMySubmissionsStore.FILTERS)list(filter,null,20);assertEquals("RETIRED",list("ALL",null,20).items().getFirst().courseState());assertEquals(0,f.f.f.jdbc.queryForObject("SELECT count(*) FROM course_enrollment WHERE course_id=?",Integer.class,course.id()));assertEquals(events,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));
  f.status(404,()->store.list(f.f.f.ids.next(),f.f.space,course.id(),f.f.author,null,20,"ALL"));f.status(404,()->store.list(f.f.group,f.f.f.ids.next(),course.id(),f.f.author,null,20,"ALL"));f.status(404,()->store.list(f.f.group,f.f.space,f.f.f.ids.next(),f.f.author,null,20,"ALL"));for(int limit:List.of(0,101))f.status(400,()->list("ALL",null,limit));for(String filter:List.of("current","OPEN_NOT_SUBMITTED","","CURRENT' OR TRUE--"))f.status(400,()->list(filter,null,20));
 }
 @Test void keysetFilteringPrecedesLimitAcrossSeveralCurrentCurriculumStudies(){
  var b=f.f.parent.parent.create(f.f.f.key()).study();course.store().curriculum(f.f.group,f.f.space,course.id(),f.f.f.owner,2,List.of(f.f.study,b.studyId()),f.f.f.trace);for(int n=0;n<12;n++){UUID study=n%2==0?f.f.study:b.studyId();UUID id=task(study);var answer=f.f.store.submit(f.f.group,f.f.space,study,id,f.f.author,0,2,f.f.f.key(),"PRIVATE ANSWER",f.f.f.trace).submission();if(n%2==0)f.store.change(f.f.group,f.f.space,study,id,answer.submissionId(),f.f.f.owner,0,new SubmissionGradeInput(0,"PRIVATE reason",1,2),f.f.f.trace);}assertEquals(13,list("ALL",null,100).items().size());assertEquals(6,list("CURRENT",null,100).items().size());assertEquals(7,list("MISSING",null,100).items().size());var seen=new ArrayList<UUID>();UUID after=null;do{var p=list("CURRENT",after,2);seen.addAll(p.items().stream().map(CourseMySubmissionsStore.Row::submissionId).toList());after=p.nextAfter();}while(after!=null);assertEquals(list("CURRENT",null,100).items().stream().map(CourseMySubmissionsStore.Row::submissionId).toList(),seen);assertEquals(6,new HashSet<>(seen).size());
 }

}
